const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;display:flex;flex-direction:column;gap:6px;height:100%;min-height:0;min-width:0;padding:10px;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;background:transparent;overflow:hidden}\n.card *{box-sizing:border-box}\n.card[data-size=\"6x6\"],.card[data-size=\"3x6\"]{padding:14px;gap:8px}\n.card[data-size=\"6x6\"]{font-size:14px}\nbutton{font:inherit;color:inherit}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.top{display:flex;align-items:center;gap:8px;min-width:0;flex:none}\n.ttl{font-weight:700;font-size:14px;white-space:nowrap}\n.tabs{display:flex;gap:4px;margin-left:auto;min-width:0}\n.tab{display:flex;align-items:center;gap:4px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--muted);border-radius:999px;padding:2px 9px 2px 3px;font-size:12px;cursor:pointer;white-space:nowrap}\n.tab i{font-style:normal;display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:50%;background:var(--soft);color:var(--ink);font-size:11px}\n.tab b{font-weight:600}\n.tab.cur{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n.tab.cur i{background:var(--on-accent);color:var(--accent)}\n.tab:disabled{opacity:.45;cursor:default}\n.pg{display:none;margin-left:auto;font-size:12px;color:var(--muted);white-space:nowrap}\n\n.body{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;overflow:auto}\n.body.fit{overflow:hidden}\n.s1{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;align-content:start;min-width:0}\n.rng{display:flex;flex-direction:column;gap:6px;min-width:0}\n.fld{display:flex;align-items:center;gap:6px;min-width:0}\n.fld span{flex:none;width:1.3em;color:var(--muted);font-size:12px}\ninput[type=date],.rin{min-width:0;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit}\n.fld input{flex:1 1 auto;width:100%}\n.chips{display:flex;gap:4px;flex-wrap:wrap}\n.chip{border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:999px;padding:0 10px;min-height:26px;font-size:12px;cursor:pointer;white-space:nowrap}\n.chip:hover{border-color:var(--accent)}\n.hint{font-size:12px;color:var(--ink)}\n.stat{padding:8px 10px;border-radius:10px;background:var(--soft);min-width:0}\n.stat b{display:block;font-size:13px}\n.stat span{display:block;font-size:12px;color:var(--muted);word-break:break-word}\n.stat.bad{border-left:3px solid var(--accent-alt)}\n\n.bar{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px;flex:none;min-width:0}\n.cnt{flex:1 1 auto;font-size:12px;color:var(--muted);white-space:nowrap}\n.cnt .lg,.btn .lg{font-style:normal}\n.cnt2{flex:none;font-size:12px;color:var(--muted)}\n.list{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:4px}\n.sec{flex:none;margin-top:4px;font-size:11px;color:var(--muted)}\n.row{flex:none;display:flex;gap:8px;align-items:flex-start;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);min-width:0}\n.row.on{background:var(--soft);border-color:var(--accent)}\n.chk{flex:none;width:18px;height:18px;margin:1px 0 0;accent-color:var(--accent);cursor:pointer}\n.rbody{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:2px}\n.rsub{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;border:0;background:none;padding:0;text-align:left;font-weight:600;color:var(--ink);cursor:pointer;word-break:break-word;min-width:0}\n.rsub.open{display:block;-webkit-line-clamp:unset}\ndiv.rsub{cursor:default}\n.rmeta{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rsn{border:0;background:none;padding:0;text-align:left;font-size:12px;color:var(--ink);cursor:pointer;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;word-break:break-word}\n.rsn.add{color:var(--muted)}\n.rsn2{font-size:12px;color:var(--muted);word-break:break-word}\n.rin{width:100%;height:28px}\n.tag{flex:none;align-self:center;font-size:11px;padding:1px 8px;border-radius:999px;background:var(--soft);color:var(--muted);border:1px solid var(--line);white-space:nowrap}\n\n.note{flex:none;padding:6px 8px;border-radius:8px;background:var(--soft);font-size:12px;word-break:break-word}\n.note b{display:block}\n.note.warn{border-left:3px solid var(--accent-alt)}\n.err{flex:none;padding:4px 8px;border-left:3px solid var(--accent-alt);background:var(--soft);font-size:12px;word-break:break-word}\n.empty{padding:14px 8px;text-align:center;color:var(--muted);font-size:12px}\n\n.foot{display:flex;gap:6px;flex:none}\n.btn{flex:1 1 0;min-width:0;min-height:32px;padding:0 8px;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-weight:600;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n.btn:disabled{opacity:.5;cursor:default}\n\n@container card (min-width:380px){\n  .s1{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n}\n@container card (max-width:300px){\n  .tabs{display:none}\n  .pg{display:block}\n  .lg,.hide-s{display:none}\n}\n.card[data-size=\"3x3\"] .chips{display:none}\n.card[data-size=\"3x3\"] .row{padding:5px 6px;gap:6px}\n";
function initialize(s){
  const n=Object.assign({},s||{});
  let ch=false;
  if(!n.range||typeof n.range!=='object'){n.range={from:'',to:''};ch=true;}
  if(!Array.isArray(n.picks)){n.picks=[];ch=true;}
  return ch?n:s;
}

function pad2(n){return n<10?'0'+n:''+n;}
function ymd(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function shiftDay(base,n){
  const d=new Date(base+'T00:00:00');
  d.setDate(d.getDate()+n);
  return ymd(d);
}
function toYmd(v){
  if(v===null||v===undefined||v==='')return '';
  if(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v))return v;
  let d;
  if(typeof v==='number')d=new Date(v<1e12?v*1000:v);
  else d=new Date(String(v));
  return isNaN(d.getTime())?'':ymd(d);
}
function firstOf(m,keys){
  for(const k of keys){
    const v=m[k];
    if(v!==null&&v!==undefined&&v!=='')return v;
  }
  return '';
}
function who(v){
  if(!v)return '';
  if(typeof v==='string')return v;
  if(Array.isArray(v))return v.map(who).filter(Boolean).join(', ');
  if(typeof v==='object')return String(v.name||v.display_name||v.address||v.email||'');
  return String(v);
}
function listOf(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){
    for(const k of ['messages','items','list','mails','emails','results','data']){
      if(Array.isArray(d[k]))return d[k];
    }
  }
  return null;
}
function normMail(m){
  if(!m||typeof m!=='object')return null;
  const id=firstOf(m,['id','message_id','messageId','uid']);
  if(id==='')return null;
  const subj=firstOf(m,['subject','title']);
  return {
    id:String(id),
    subject:String(subj||'(无主题)'),
    from:who(firstOf(m,['from','sender','from_name','from_address'])),
    date:toYmd(firstOf(m,['date','received_at','receivedAt','internal_date','sent_at','time','timestamp']))
  };
}


function mount(ctx){
  const {root,el,state,ui,update,redraw,day,host}=ctx;
  if(!ui.step)ui.step=1;
  const range=(state&&state.range)||{from:'',to:''};
  const picks=(state&&Array.isArray(state.picks))?state.picks:[];
  const pickMap={};
  picks.forEach(p=>{pickMap[p.id]=p;});
  const rangeOk=!!(range.from&&range.to&&range.from<=range.to);
  const ok=ui.mailOk||null;
  const inRange=ok?ok.mails.filter(m=>rangeOk&&m.date&&m.date>=range.from&&m.date<=range.to).sort((a,b)=>(a.date<b.date?1:(a.date>b.date?-1:0))):[];
  const inIds={};
  inRange.forEach(m=>{inIds[m.id]=1;});
  const extra=picks.filter(p=>!inIds[p.id]);
  const checked=picks.filter(p=>p.checked);
  const names=['范围','建议','确认','结果'];
  let timer=0;

  const kids=a=>a.filter(x=>x!==null&&x!==undefined&&x!==false);
  const h=(tag,cls,...ch)=>el(tag,{class:cls},...kids(ch));
  const meta=(p,saved)=>[p.from,p.date,saved?'已保存':''].filter(Boolean).join(' · ');
  const go=k=>{ui.step=k;ui.err='';redraw();};
  const save=fn=>{
    ui.err='';
    return update(fn).catch(e=>{ui.err='保存失败：'+((e&&e.message)||'请重试');redraw();});
  };

  async function loadMail(){
    if(ui.mailBusy)return;
    ui.mailBusy=true;ui.mailErr=null;redraw();
    try{
      const r=await host.fetchData('connected.mail.message-list');
      if(!r||r.status!=='ok'){
        throw new Error(String((r&&(r.errorCode||r.error||r.status))||'no_response'));
      }
      const arr=listOf(r.data);
      if(!arr)throw new Error('unrecognized_data_shape');
      const mails=[];
      let skipped=0;
      arr.forEach(m=>{const x=normMail(m);if(x)mails.push(x);else skipped++;});
      const t=new Date();
      ui.mailOk={mails:mails,skipped:skipped,at:pad2(t.getHours())+':'+pad2(t.getMinutes())};
    }catch(e){
      const raw=String((e&&(e.errorCode||e.message))||e||'unknown');
      ui.mailErr={raw:raw,bind:/permission|denied|forbidden|unauthor|bind|connect/i.test(raw)};
    }
    ui.mailBusy=false;redraw();
  }

  function setRange(patch){
    return save(s=>Object.assign({},s,{range:Object.assign({},s.range||{},patch)}));
  }
  function setPick(m,patch){
    return save(s=>{
      const arr=(s.picks||[]).slice();
      const i=arr.findIndex(p=>p.id===m.id);
      if(i>=0)arr[i]=Object.assign({},arr[i],patch);
      else arr.push(Object.assign({id:m.id,subject:m.subject,from:m.from,date:m.date,reason:'',checked:false},patch));
      return Object.assign({},s,{picks:arr.filter(p=>p.checked||p.reason)});
    });
  }
  function toggleAll(on){
    return save(s=>{
      const arr=(s.picks||[]).slice();
      inRange.forEach(m=>{
        const i=arr.findIndex(p=>p.id===m.id);
        if(i>=0)arr[i]=Object.assign({},arr[i],{checked:on});
        else if(on)arr.push({id:m.id,subject:m.subject,from:m.from,date:m.date,reason:'',checked:true});
      });
      return Object.assign({},s,{picks:arr.filter(p=>p.checked||p.reason)});
    });
  }


  function header(){
    const tabs=names.map((n,i)=>{
      const k=i+1;
      return el('button',{type:'button',class:'tab'+(ui.step===k?' cur':''),disabled:k===4&&!ui.done,'aria-label':'第'+k+'步 '+n,onclick:()=>go(k)},
        h('i','',String(k)),h('b','',n));
    });
    return h('div','top',
      h('div','ttl','整理收件箱'),
      h('div','tabs',...tabs),
      h('div','pg',ui.step+'/4 '+names[ui.step-1]));
  }

  function dateField(lab,key,aria){
    return h('label','fld',
      h('span','',lab),
      el('input',{type:'date',value:range[key]||'','aria-label':aria,onchange:ev=>{setRange({[key]:ev.target.value});}}));
  }

  function statBlock(){
    let t='',d='',bad=false;
    if(ui.mailBusy){
      t='正在读取邮件…';d='只读取邮件元数据。';
    }else if(ui.mailErr){
      bad=true;
      if(ui.mailErr.bind){
        t='⚠ 还没连接邮箱';
        d='请先在平台为这张卡片连接邮箱，再点“读取邮件”。（'+ui.mailErr.raw+'）';
      }else{
        t='⚠ 读取失败';
        d=ui.mailErr.raw+(ok?'。已保留上次读取的 '+ok.mails.length+' 封。':'');
      }
    }else if(ok){
      t='已读取 '+ok.mails.length+' 封';
      d=(rangeOk?'所选范围内 '+inRange.length+' 封':'请选好完整的日期范围');
      const nd=ok.mails.filter(m=>!m.date).length;
      if(nd)d+='；另有 '+nd+' 封无日期，未计入';
      if(ok.skipped)d+='；'+ok.skipped+' 封缺少编号，已忽略';
      d+=' · 读取于 '+ok.at;
    }else{
      t='尚未读取';
      d=rangeOk?'点“读取邮件”获取所选范围的邮件。':'先选好开始和结束日期，再读取邮件。';
    }
    return h('div','stat'+(bad?' bad':''),h('b','',t),h('span','',d));
  }

  function step1(){
    const chips=[7,30,90].map(n=>el('button',{type:'button',class:'chip',onclick:()=>{
      const t=day();
      setRange({from:shiftDay(t,-(n-1)),to:t});
    }},'近'+n+'天'));
    const swapped=range.from&&range.to&&range.from>range.to;
    const rng=h('div','rng',
      dateField('起','from','开始日期'),
      dateField('止','to','结束日期'),
      swapped?h('div','hint','⚠ 开始日期晚于结束日期'):null,
      h('div','chips',...chips));
    return h('div','body',h('div','s1',rng,statBlock()));
  }


  function rowEl(m,saved){
    const p=pickMap[m.id];
    const on=!!(p&&p.checked);
    const reason=(p&&p.reason)||'';
    const open=ui.openId===m.id;
    let reasonNode;
    if(ui.editId===m.id){
      let fin=false;
      const done=v=>{
        if(fin)return;
        fin=true;ui.editId='';
        const t=v.trim();
        if(t===reason)redraw();else setPick(m,{reason:t});
      };
      reasonNode=el('input',{type:'text',class:'rin',value:reason,placeholder:'写下归档理由','aria-label':'归档理由',
        onkeydown:ev=>{
          if(ev.key==='Enter'){ev.preventDefault();done(ev.target.value);}
          else if(ev.key==='Escape'){fin=true;ui.editId='';redraw();}
        },
        onchange:ev=>{done(ev.target.value);}});
    }else{
      reasonNode=el('button',{type:'button',class:'rsn'+(reason?'':' add'),onclick:()=>{ui.editId=m.id;redraw();}},
        reason?'理由：'+reason:'＋ 写理由');
    }
    return h('div','row'+(on?' on':''),
      el('input',{type:'checkbox',class:'chk',checked:on,'aria-label':'归档：'+m.subject,onchange:ev=>{setPick(m,{checked:ev.target.checked});}}),
      h('div','rbody',
        el('button',{type:'button',class:'rsub'+(open?' open':''),onclick:()=>{ui.openId=open?'':m.id;redraw();}},m.subject),
        h('div','rmeta',meta(m,saved)),
        reasonNode));
  }

  function step2(){
    const allOn=inRange.length>0&&inRange.every(m=>pickMap[m.id]&&pickMap[m.id].checked);
    const bar=h('div','bar',
      h('span','cnt',h('i','lg','范围内 '),inRange.length+' 封 · 已选 '+checked.length),
      inRange.length?el('button',{type:'button',class:'chip hide-s',onclick:()=>toggleAll(!allOn)},allOn?'取消全选':'全选'):null,
      el('button',{type:'button',class:'chip',onclick:()=>{ui.aiOpen=!ui.aiOpen;redraw();}},'AI 列建议'));
    const ai=ui.aiOpen?h('div','note warn',
      h('b','','AI 建议暂未接入'),
      h('span','','当前没有可调用的 AI 推理接口，无法自动判断哪些邮件该归档、也给不出理由。请先手动勾选并写理由；清单会保存。')):null;
    let list;
    if(!ok&&!picks.length){
      list=h('div','empty','还没有邮件。先到“范围”读取邮件。');
    }else{
      const items=[];
      if(ok&&!inRange.length)items.push(h('div','empty',rangeOk?'所选范围内没有邮件。':'请先在“范围”选好日期。'));
      inRange.forEach(m=>{items.push(rowEl(m,false));});
      if(extra.length){
        items.push(h('div','sec','已保存，但不在当前列表中'));
        extra.forEach(p=>{items.push(rowEl(p,true));});
      }
      list=h('div','list',...items);
    }
    return h('div','body fit',bar,ai,list);
  }

  function step3(){
    if(!checked.length)return h('div','body',h('div','empty','还没有勾选邮件。回到“建议”勾选要处理的邮件。'));
    return h('div','body fit',
      h('div','note warn',h('b','','确认前请注意'),h('span','','邮件归档接口尚未接入，点“确认归档”不会真的移动邮件。')),
      h('div','cnt2','将归档 '+checked.length+' 封（可取消勾选或改理由）'),
      h('div','list',...checked.map(p=>rowEl(p,!inIds[p.id]))));
  }


  function step4(){
    const rows=checked.map(p=>h('div','row rr',
      h('div','rbody',
        h('div','rsub s',p.subject),
        h('div','rmeta',meta(p,false)),
        p.reason?h('div','rsn2','理由：'+p.reason):null),
      h('span','tag','未执行')));
    return h('div','body fit',
      h('div','note warn',
        h('b','','邮件归档暂未接入'),
        h('span','','没有任何邮件被归档，所以没有“成功/失败”结果，也没有可单独重试的项目。下面 '+checked.length+' 封保持“未执行”，待平台开放归档能力后再处理。')),
      rows.length?h('div','list',...rows):h('div','empty','清单为空。'));
  }

  function btn(label,fn,pri,dis){
    return el('button',{type:'button',class:'btn'+(pri?' pri':''),disabled:!!dis,onclick:fn},...(Array.isArray(label)?label:[label]));
  }

  function footer(){
    const k=checked.length;
    if(ui.step===1){
      const hasOk=!!ok;
      return h('div','foot',
        btn(ui.mailBusy?'读取中…':(hasOk?'重新读取':'读取邮件'),loadMail,!hasOk,!rangeOk||!!ui.mailBusy),
        btn('下一步',()=>go(2),hasOk,!(rangeOk&&(hasOk||picks.length>0))));
    }
    if(ui.step===2){
      return h('div','foot',
        btn('上一步',()=>go(1)),
        btn(['下一步',h('i','lg',' · '+k+' 封')],()=>go(3),true,!k));
    }
    if(ui.step===3){
      return h('div','foot',
        btn('上一步',()=>go(2)),
        btn(['确认归档',h('i','lg',' '+k+' 封')],()=>{ui.done=true;ui.err='';ui.step=4;redraw();},true,!k));
    }
    return h('div','foot',btn('返回修改',()=>go(2)),btn('回到范围',()=>go(1)));
  }

  function render(){
    let content;
    if(ui.step===1)content=step1();
    else if(ui.step===2)content=step2();
    else if(ui.step===3)content=step3();
    else content=step4();
    root.append(header(),content);
    if(ui.err)root.append(h('div','err','⚠ '+ui.err));
    root.append(footer());
    if(ui.editId){
      timer=setTimeout(()=>{const i=root.querySelector('.rin');if(i)i.focus();},0);
    }
  }
  render();
  return ()=>{clearTimeout(timer);};
